contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _val) public payable {
        c.SetMinSum(_val); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;

        bool setMinSumReverted;
        c.SetMinSum(_val); bool __rev0 = __ESBMC_reverted(); if (__rev0) { setMinSumReverted = true; } else { setMinSumReverted = false; }

        assert(setMinSumReverted && c.MinSum() == _val);
    }
    receive() external payable {}
}

